  const st = { session:null, admin:null, authSessionRevocationReady:false, authSessionRevocationReason:'Backend ainda não validado.', overview:null, live:[], security:[], accessSecurity:[], legacy:[], rankings:[], classSubjects:[], releases:[], exerciseMeta:[], activityClass:'', activitySubject:'', monitorClass:'all', monitorSearch:'', currentView:'overview', selectedStudent:null, student360:null, query:'', autoRefreshTimer:null, lastSyncAt:null, securitySeverity:'open', securitySource:'all', securityQuery:'', reportClass:'all', reportQuery:'', reportWindow:'all', reportFocus:'all', subjects:[], releaseDataHealthy:false, releaseSyncedAt:null, releaseError:'', editReleaseVersion:'' };
