  function maps(){ const o=st.overview||{}, classes=o.classes||[], memberships=o.memberships||[], profiles=o.profiles||[], prereg=o.preregistrations||[], progress=o.progress||[], exercises=o.exercises||[]; const classMap=new Map(classes.map(x=>[String(x.id),x])), profMap=new Map(profiles.map(x=>[String(x.id),x])), preregByClaim=new Map(prereg.filter(x=>x.claimed_user_id).map(x=>[String(x.claimed_user_id),x])), memByUser=new Map(); for(const m of memberships){ const k=String(m.user_id); if(!memByUser.has(k))memByUser.set(k,[]); memByUser.get(k).push(m); } const exMap=new Map(exercises.map(x=>[String(x.id),x])); return {classes,memberships,profiles,prereg,progress,exercises,classMap,profMap,preregByClaim,memByUser,exMap}; }
