  function uaLabel(ua=''){const s=String(ua||'');const mobile=/Android|iPhone|iPad|Mobile/i.test(s);const os=/Android/i.test(s)?'Android':/iPhone|iPad|iOS/i.test(s)?'iOS/iPadOS':/Windows/i.test(s)?'Windows':/Mac OS|Macintosh/i.test(s)?'macOS':/Linux/i.test(s)?'Linux':'SO não identificado';const browser=/Edg\//i.test(s)?'Edge':/OPR\//i.test(s)?'Opera':/CriOS|Chrome\//i.test(s)?'Chrome':/FxiOS|Firefox\//i.test(s)?'Firefox':/Safari\//i.test(s)?'Safari':'Navegador não identificado';return `${mobile?'Mobile':'Desktop'} · ${os} · ${browser}`;}
  function severityRank(v='info'){return({critical:4,high:3,warning:2,info:1}[String(v).toLowerCase()]||0);}
