  function filteredAccessSecurity(){const q=st.securityQuery.trim().toLowerCase();return st.accessSecurity.filter(x=>{if(st.securitySeverity==='open'&&!securityOpen(x))return false;if(['critical','high','warning','info'].includes(st.securitySeverity)&&String(x.severity||'info')!==st.securitySeverity)return false;if(st.securitySource!=='all'&&securityCategory(x)!==st.securitySource)return false;if(q){const hay=[accessActor(x),accessEvent(x),accessLocation(x),x.ip_address,x.asn,x.organization,x.user_agent,x.risk_code].join(' ').toLowerCase();if(!hay.includes(q))return false;}return true;}).sort((a,b)=>severityRank(b.severity)-severityRank(a.severity)||Date.parse(b.created_at||0)-Date.parse(a.created_at||0));}
  function exportSecurityCsv(){const rows=filteredAccessSecurity();const cols=['usuario','evento','severidade','local','ip','asn','rede','dispositivo','risk_code','horario','revisado'];const quote=v=>`"${String(v??'').replaceAll('\"','\"\"')}"`;const lines=[cols.join(';'),...rows.map(x=>[accessActor(x),accessEvent(x),x.severity||'info',accessLocation(x),x.ip_address||'',x.asn||'',x.organization||'',uaLabel(x.user_agent),x.risk_code||'',x.created_at||'',x.acknowledged_at||''].map(quote).join(';'))];const blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`agv-seguranca-${new Date().toISOString().slice(0,10)}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

