  function tableHtml(headers,rows){ return `<div class="table-wrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c??'—'}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty">Sem dados.</td></tr>`}</tbody></table></div>`; }

  function combinedUsers(){ const m=maps(), rows=[]; for(const q of m.prereg){ const p=q.claimed_user_id?m.profMap.get(String(q.claimed_user_id)):null, id=p?.id||null, cls=m.classMap.get(String(q.class_id))|| (id?classForUser(id):null); rows.push({prereg:q,profile:p,id,name:p?.full_name||q.full_name,email:p?.email||q.institutional_email,class:cls,active:p?p.active:q.active,last:p?.last_login_at||null,online:id?!!activeSessionFor(id):false,pending:id?pendingCount(id):0}); } for(const p of m.profiles){ if(!m.preregByClaim.has(String(p.id))){ rows.push({prereg:null,profile:p,id:p.id,name:p.full_name,email:p.email,class:classForUser(p.id),active:p.active,last:p.last_login_at,online:!!activeSessionFor(p.id),pending:pendingCount(p.id)}); } } return rows; }
  function renderUsers(){ return `<div class="panel"><div class="panel-head"><h2>Usuários e autorizados</h2><div class="toolbar"><input id="user-search" placeholder="Nome, e-mail ou CGM"><select id="user-class"><option value="">Todas as turmas</option>${maps().classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><select id="user-status"><option value="">Todos</option><option value="active">Ativos</option><option value="inactive">Inativos</option><option value="online">Online</option><option value="unclaimed">Não ativados</option></select></div></div><div id="users-table">${usersTable(combinedUsers())}</div></div>`; }
