  function renderActivities(){ const m=maps(), classId=st.activityClass||String(m.classes[0]?.id||'');st.activityClass=classId;const subjectOptions=subjectsForClass(classId);if(!st.activitySubject||!subjectOptions.some(x=>String(x.id)===String(st.activitySubject)))st.activitySubject=String(subjectOptions[0]?.id||'');const exs=displayedActivities(), claimed=m.prereg.filter(x=>String(x.class_id)===String(classId)&&x.active&&x.claimed_user_id).length, total=m.prereg.filter(x=>String(x.class_id)===String(classId)&&x.active).length; const rows=exs.map(e=>{const p=m.progress.filter(x=>String(x.exercise_id)===String(e.id)),r=classRelease(e.id,classId),[label,kind]=releaseStatus(r,e),exceptions=st.releases.filter(x=>String(x.exercise_id)===String(e.id)&&x.student_id).length;return [`<strong>${esc(e.exercise_number?String(e.exercise_number).padStart(2,'0')+' — ':'')}${esc(e.title)}</strong>`,statusPill(label,kind),r?.release_at?fmtDate(r.release_at):'—',r?.lock_at?fmtDate(r.lock_at):'—',`${p.filter(x=>['in_progress','started'].includes(x.status)&&!isPartial(x)).length} / ${p.filter(isPartial).length} / ${p.filter(x=>x.status==='completed').length}`,exceptions?statusPill(`${exceptions} exceção(ões)`,'warn'):'—',`<button class="ghost tiny" data-configactivity="${e.id}">Configurar</button>`];}); return `<div class="panel"><div class="panel-head activity-head"><div><h2>Central de Atividades</h2><span class="muted">Liberação organizada por turma e disciplina. Ações em massa atuam somente na disciplina selecionada.</span></div><div class="activity-toolbar"><select id="activity-class">${m.classes.map(c=>`<option value="${c.id}" ${String(c.id)===String(classId)?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select id="activity-subject">${subjectOptions.map(x=>`<option value="${x.id}" ${String(x.id)===String(st.activitySubject)?'selected':''}>${esc(x.name)}</option>`).join('')}</select><button class="ghost" id="release-all" type="button">Liberar disciplina</button><button class="ghost danger-outline" id="block-all" type="button">Bloquear disciplina</button></div></div><div class="activity-summary"><span>${exs.length} atividade(s) na disciplina</span><span>${total} aluno(s) ativo(s) no roster</span><span>${claimed} conta(s) ativada(s) apta(s) a exceção individual</span></div>${exs.length?tableHtml(['Atividade','Disponibilidade','Abre em','Encerra em','Fazendo / Parcial / Concl.','Exceções','Ação'],rows):'<div class="empty">Nenhuma atividade nesta disciplina.</div>'}</div>`; }
  function renderCorrections(){ const m=maps(), rows=m.progress.filter(x=>x.approval_status==='pending'||x.approval_status==='changes_requested'||isPartial(x)).sort((a,b)=>Date.parse(b.last_activity_at||0)-Date.parse(a.last_activity_at||0)); return `<div class="panel"><div class="panel-head"><h2>Fila de acompanhamento</h2><span class="muted">Revisões, ajustes solicitados e entregas parciais.</span></div>${tableHtml(['Aluno','Atividade','Estado','Nota','Tentativas','Última atividade','Ação'],rows.map(x=>{const [label,kind]=progressState(x);return [studentName(x.student_id),exerciseName(x.exercise_id),statusPill(label,kind),x.submitted_score==null?'—':`${exerciseScore(x)}%`,String(x.attempts||0),fmtDate(x.last_activity_at),`<button class="ghost tiny" data-student360="${x.student_id}">Abrir aluno</button>`]}))}</div>`; }
